import React, { useEffect, useMemo, useState } from 'react';
import { getCart, totalAmount, clearCart } from '../lib/cart';
import BuyerLayout from '../components/BuyerLayout';
import api from '../lib/api';
import { MIDTRANS_CLIENT_KEY } from '../config';

function loadMidtrans(clientKey){
  return new Promise((resolve, reject) => {
    if (document.getElementById('midtrans-script')) return resolve();
    const s = document.createElement('script');
    s.id = 'midtrans-script';
    s.src = `https://app.sandbox.midtrans.com/snap/snap.js`;
    s.setAttribute('data-client-key', clientKey);
    s.onload = () => resolve();
    s.onerror = reject;
    document.body.appendChild(s);
  });
}

export default function Checkout(){
  const [items, setItems] = useState([]);
  const [form, setForm] = useState({
    name: '',
    phone: '',
    address: '',
    province_id: '',
    province_name: '',
    city_id: '',
    city_name: '',
    postal_code: '',
    courier: 'jne',
    shipping_service: '',
  });
  const [submitting, setSubmitting] = useState(false);
  const [provinces, setProvinces] = useState([]);
  const [cities, setCities] = useState([]);
  const [shipOptions, setShipOptions] = useState([]);
  const [shippingCost, setShippingCost] = useState(0);

  useEffect(()=>{
    setItems(getCart());
    const onUpd = ()=> setItems(getCart());
    window.addEventListener('cart_updated', onUpd);
    return ()=> window.removeEventListener('cart_updated', onUpd);
  },[]);

  const subtotal = useMemo(()=> totalAmount(), [items]);
  const grandTotal = useMemo(()=> subtotal + (shippingCost||0), [subtotal, shippingCost]);

  // Load provinces (RajaOngkir via backend) on mount
  useEffect(()=>{
    api.get('/shipping/provinces')
      .then(r=> setProvinces(r.data || []))
      .catch(()=> setProvinces([]));
  },[]);

  function onProvinceChange(id){
    const selected = provinces.find(p=> String(p.province_id) === String(id));
    setForm(prev => ({...prev, province_id: id, province_name: selected?.province || '' , city_id: '', city_name: ''}));
    setCities([]);
    if (!id) return;
    api.get(`/shipping/cities?province=${id}`)
      .then(r=> setCities(r.data || []))
      .catch(()=> setCities([]));
  }

  async function checkShipping(){
    if (!form.city_id || !form.courier){
      return alert('Pilih provinsi/kota dan kurir dulu.');
    }
    try{
      const r = await api.post('/shipping/options', {
        destination_city_id: form.city_id,
        courier: form.courier,
        items: items.map(i=> ({ product_id: i.product_id, quantity: i.quantity }))
      });
      const options = r.data?.options || [];
      setShipOptions(options);
      if (options[0]){
        setForm(prev=> ({...prev, shipping_service: options[0].service }));
        setShippingCost(options[0].cost||0);
      }
    }catch(err){
      alert('Gagal cek ongkir');
      setShipOptions([]);
      setShippingCost(0);
    }
  }

  async function pay(){
    if (!items.length) return alert('Keranjang kosong');

    const token = localStorage.getItem('hr_token');
    if (!token) {
      if (window.confirm('Anda harus login terlebih dahulu. Login sekarang?')) window.location.href = '/login';
      return;
    }

    // minimal validation
    if (!form.name || !form.phone || !form.address || !form.city_id || !form.province_id || !form.postal_code) {
      return alert('Lengkapi data pengiriman terlebih dahulu.');
    }
    if (!form.shipping_service || !form.courier) {
      return alert('Silakan cek ongkir dan pilih layanan pengiriman.');
    }

    try{
      setSubmitting(true);
      await loadMidtrans(MIDTRANS_CLIENT_KEY);
      const resp = await api.post('/checkout', {
        items,
        customer: {
          name: form.name,
          phone: form.phone,
        },
        shipping: {
          address: form.address,
          city: form.city_name,
          province: form.province_name,
          postal_code: form.postal_code,
          method: form.shipping_service,
          cost: shippingCost,
          destination_city_id: form.city_id,
          courier: form.courier,
          service: form.shipping_service,
        }
      });
      const token_snap = resp.data.snap_token;
      const orderId = resp.data?.order?.order_number;
      if (!token_snap) return alert('Gagal membuat transaksi');
      window.snap.pay(token_snap, {
        onSuccess: function(){
          clearCart();
          if (orderId) api.post('/midtrans/refresh', { order_id: orderId }).catch(()=>{});
          
          // Show success message with order info
          const orderInfo = resp.data?.order;
          let message = 'Pembayaran berhasil!\n\n';
          message += `Nomor Order: ${orderId}\n`;
          if (orderInfo?.courier) {
            message += `Kurir: ${orderInfo.courier}\n`;
          }
          message += '\nNomor resi akan diberikan setelah paket dikirim.';
          alert(message);
          
          window.location.href = '/';
        },
        onPending: function(){
          alert('Pembayaran pending');
          if (orderId) api.post('/midtrans/refresh', { order_id: orderId }).catch(()=>{});
        },
        onError: function(){
          alert('Pembayaran error');
        }
      });
    }catch(err){
      const data = err.response?.data;
      let msg = 'Checkout gagal';
      if (data) msg = data.message || data.details || data.error || msg;
      alert(msg);
      console.error('Checkout error', err);
    }finally{
      setSubmitting(false);
    }
  }

  return (
    <div className="font-sans">
      <PublicHeader/>
      <div className="container py-6">
        <h2 className="text-2xl font-semibold mb-4">Checkout</h2>
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6">
          <div className="lg:col-span-2 card p-4">
            <h3 className="font-semibold mb-3">Data Pengiriman</h3>
            <div className="grid grid-cols-1 md:grid-cols-2 gap-3">
              <div>
                <label className="block text-sm font-medium mb-1">Nama Lengkap</label>
                <input className="input" value={form.name} onChange={e=>setForm({...form, name: e.target.value})} placeholder="Nama lengkap" />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">No. HP</label>
                <input className="input" value={form.phone} onChange={e=>setForm({...form, phone: e.target.value})} placeholder="08xxxxxxxxxx" />
              </div>
              <div className="md:col-span-2">
                <label className="block text-sm font-medium mb-1">Alamat</label>
                <input className="input" value={form.address} onChange={e=>setForm({...form, address: e.target.value})} placeholder="Nama jalan, RT/RW, kelurahan" />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Provinsi</label>
                <select className="input" value={form.province_id} onChange={e=> onProvinceChange(e.target.value)}>
                  <option value="">Pilih Provinsi</option>
                  {provinces.map(p=> <option key={p.province_id} value={p.province_id}>{p.province}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Kota/Kabupaten</label>
                <select className="input" value={form.city_id} onChange={e=>{
                  const v = e.target.value; const c = cities.find(x=> String(x.city_id)===String(v));
                  setForm(prev=> ({...prev, city_id: v, city_name: c?.city_name || ''}));
                }}>
                  <option value="">Pilih Kota/Kabupaten</option>
                  {cities.map(c=> <option key={c.city_id} value={c.city_id}>{c.city_name}</option>)}
                </select>
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Kode Pos</label>
                <input className="input" value={form.postal_code} onChange={e=>setForm({...form, postal_code: e.target.value})} placeholder="XXXXX" />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Kurir</label>
                <select className="input" value={form.courier} onChange={e=> setForm({...form, courier: e.target.value})}>
                  <option value="jne">JNE</option>
                  <option value="tiki">TIKI</option>
                  <option value="pos">POS</option>
                </select>
              </div>
              <div className="md:col-span-2">
                <button type="button" onClick={checkShipping} className="btn btn-outline">Cek Ongkir</button>
              </div>
              {shipOptions.length>0 && (
                <div className="md:col-span-2">
                  <label className="block text-sm font-medium mb-1">Pilih Layanan</label>
                  <div className="space-y-2">
                    {shipOptions.map(opt => (
                      <label key={opt.service} className="flex items-center gap-2">
                        <input type="radio" name="svc" checked={form.shipping_service === opt.service} onChange={()=>{ setForm(prev=> ({...prev, shipping_service: opt.service })); setShippingCost(opt.cost||0); }} />
                        <span className="text-sm">{opt.courier} {opt.service} — {opt.description} (ETD: {opt.etd||'-'})</span>
                        <span className="ml-auto font-medium">Rp {opt.cost}</span>
                      </label>
                    ))}
                  </div>
                </div>
              )}
            </div>
          </div>

          <div className="card p-4 h-max">
            <h3 className="font-semibold mb-3">Ringkasan Pesanan</h3>
            <div className="space-y-2 text-sm">
              {(items||[]).map(it => (
                <div key={it.product_id} className="flex justify-between">
                  <span className="truncate mr-2">{it.name} × {it.quantity}</span>
                  <span>Rp {(it.price||0)*(it.quantity||0)}</span>
                </div>
              ))}
              <div className="flex justify-between pt-2 border-t">
                <span>Subtotal</span>
                <span>Rp {subtotal}</span>
              </div>
              <div className="flex justify-between">
                <span>Ongkir {form.courier?.toUpperCase()} {form.shipping_service}</span>
                <span>Rp {shippingCost||0}</span>
              </div>
              <div className="flex justify-between text-lg font-semibold pt-2 border-t">
                <span>Total</span>
                <span>Rp {grandTotal}</span>
              </div>
              <button disabled={submitting} onClick={pay} className="btn btn-primary w-full mt-2">{submitting? 'Memproses…' : 'Bayar Sekarang'}</button>
              <a href="/cart" className="btn btn-outline w-full">Kembali ke Keranjang</a>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
